import json

# Try to find JSON in the agent output
text = str(agent_out)

# Look for the CLI JSON envelope {"tool": ..., "result": ...}
json_start = text.find('{"tool"')
if json_start == -1:
    json_start = text.find('{"order')
if json_start == -1:
    json_start = text.find('{')

if json_start >= 0:
    # Find matching closing brace
    depth = 0
    json_end = json_start
    for i in range(json_start, len(text)):
        if text[i] == '{':
            depth += 1
        elif text[i] == '}':
            depth -= 1
            if depth == 0:
                json_end = i + 1
                break

    json_str = text[json_start:json_end]
    try:
        parsed = json.loads(json_str)
        # Unwrap CLI envelope
        if 'result' in parsed:
            order_data = parsed['result']
        else:
            order_data = parsed
        print("Successfully parsed order data!")
        print(f"Keys: {list(order_data.keys())}")
        print(json.dumps(order_data, indent=2, default=str)[:1000])
    except json.JSONDecodeError as e:
        order_data = None
        print(f"JSON parse failed: {e}")
        print(f"Attempted to parse: {json_str[:200]}")
else:
    order_data = None
    print("No JSON found in agent output")
    print(f"Agent output: {text[:500]}")

