import json

order = data['orders_match'][0] if data.get('orders_match') else None
items = data.get('items', [])
products = {p['product_id']: p for p in data.get('products', [])}
warranties = data.get('warranties', [])
customer = data.get('customer', {})

lines = []
lines.append("=" * 65)
lines.append("ORDER DETAILS REPORT — ORD-CCC96C")
lines.append("=" * 65)

if order:
    lines.append("")
    lines.append("ORDER INFORMATION")
    lines.append("-" * 40)
    for k, v in order.items():
        if v is not None and v != "":
            lines.append(f"  {k.replace('_',' ').title():30s}: {v}")

    if customer:
        lines.append("")
        lines.append("CUSTOMER INFORMATION")
        lines.append("-" * 40)
        for k, v in customer.items():
            if v is not None and v != "" and k != 'skill_ids_json':
                lines.append(f"  {k.replace('_',' ').title():30s}: {v}")

    if items:
        lines.append("")
        lines.append(f"ORDER ITEMS ({len(items)})")
        lines.append("-" * 40)
        for idx, item in enumerate(items, 1):
            lines.append(f"\n  --- Item {idx} ---")
            for k, v in item.items():
                if v is not None and v != "":
                    lines.append(f"  {k.replace('_',' ').title():30s}: {v}")
            pid = item.get('product_id', '')
            if pid in products:
                lines.append(f"  {'Product Details':30s}:")
                for k, v in products[pid].items():
                    if v is not None and v != "":
                        lines.append(f"    {k.replace('_',' ').title():28s}: {v}")

    if warranties:
        lines.append("")
        lines.append(f"WARRANTIES ({len(warranties)})")
        lines.append("-" * 40)
        for idx, w in enumerate(warranties, 1):
            lines.append(f"\n  --- Warranty {idx} ---")
            for k, v in w.items():
                if v is not None and v != "":
                    lines.append(f"  {k.replace('_',' ').title():30s}: {v}")

    lines.append("")
    lines.append("=" * 65)
    lines.append("RAW JSON DATA")
    lines.append("=" * 65)
    raw = {"order": order, "items": items, "products": list(products.values()), "warranties": warranties, "customer": customer}
    lines.append(json.dumps(raw, indent=2, default=str))
else:
    lines.append("\nORDER NOT FOUND IN DATABASE")
    if data.get('sample_order_ids'):
        lines.append(f"Sample existing order IDs: {data['sample_order_ids']}")

lines.append("")
lines.append("END OF REPORT")

full_report = "\n".join(lines)
print(f"Report length: {len(full_report)} chars")
print(full_report[:1500])
